function formulasChart(stage) {
  const order = ["product", "slider", "fraction", "brackets", "call", "domain"];
  const at = (s) => order.indexOf(stage) >= order.indexOf(s);
  const functions = [fn("f1", at("slider") ? "a*x(4 - x)" : "0.5x(4 - x)", { domain: at("domain") ? "0:4" : "" })];
  if (at("fraction"))
    functions.push(fn("f2", at("brackets") ? "1/(2x)" : "1/2x", { color: "blue" }));
  if (at("call"))
    functions.push(fn("f3", "f1(x - 4)", { color: "red" }));
  return chart({ functions, parameters: at("slider") ? [slider("a", 1)] : [] });
}
