    documentSetup: true,
    title: "",
    size_x_cm: 10,
    size_y_cm: 10,
    show_axis_label: true,
    axis_label_x: "x",
    axis_label_y: "y",
    showAxis: true,
    showLargeGrid: false,
    showSmallGrid: false,
    gridSize: 5,
    majorTickNum: 8,
    xmin: "-0.5",
    xmax: "10",
    ymin: "-0.5",
    ymax: "5",
    zmin: "-5",
    zmax: "5",
    axis_style: "box",
    coordinateSystem: "cartesian",
    axis_label_x_polar: "",
    axis_label_y_polar: "",
    axis_label_z: "z",
    rotationX: 30,
    rotationZ: 45,
    zoom3D: 1,
    boxAspect: "true",
    previewSize: 760,
    functions: [],
    functions3D: [],
    tools: [],
    annotations: [],
    parameters: [],
    variables: "x, y",
    equalScale: false,
    showSlidersInNote: true
