    axis_label_y: "y",
    showAxis: true,
    showLargeGrid: false,
    showSmallGrid: false,
    gridSize: 5,
    majorTickNum: 8,
    xmin: "-0.5",
    xmax: "10",
    ymin: "-0.5",
    ymax: "5",
    zmin: "-5",
    zmax: "5",
    axis_style: "box",
    coordinateSystem: "cartesian",
    axis_label_x_polar: "",
